#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;   /* storage size */
    size_t size;       /* bytes currently stored (0 <= size <= capacity) */
    size_t head;       /* index of oldest byte */
    size_t tail;       /* next free index after the youngest byte */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->size   = 0;
    rb->head   = 0;
    rb->tail   = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static size_t wrapped_add(size_t v, size_t inc, size_t limit)
{
    v += inc;
    if (v >= limit)
        v -= limit;
    return v;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data)
        return 0;

    if (len == 0 || rb->size == rb->capacity)
        return 0;

    /* free space available */
    size_t avail = rb->capacity - rb->size;
    size_t to_write = len < avail ? len : avail;

    /* region 1: tail -> end of buffer */
    size_t region1 = to_write;
    if (region1 > rb->capacity - rb->tail)
        region1 = rb->capacity - rb->tail;

    if (region1) {
        if (region1 < to_write)
            /* need wrap: copy tail..end, then 0..remainder */
            ; /* handled below by loop */
        else {
            /* no wrap possible */
        }
    }

    /* Simple two-copy approach: */
    for (size_t i = 0; i < to_write; i++) {
        rb->buf[rb->tail] = data[i];
        rb->tail = wrapped_add(rb->tail, 1, rb->capacity);
    }

    rb->size += to_write;
    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->size == 0)
        return 0;

    if (len > rb->size)
        len = rb->size;

    for (size_t i = 0; i < len; i++) {
        out[i] = rb->buf[rb->head];
        rb->head = wrapped_add(rb->head, 1, rb->capacity);
    }

    rb->size -= len;
    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->size == 0)
        return 0;

    /* use a temporary head copy */
    size_t rd = 0;
    size_t lim = len < rb->size ? len : rb->size;
    size_t h = rb->head;

    for (rd = 0; rd < lim; rd++) {
        out[rd] = rb->buf[h];
        h = wrapped_add(h, 1, rb->capacity);
    }

    return rd;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->size   = 0;
    rb->head   = 0;
    rb->tail   = 0;
}

