{
    if (!r || !out || r->sz == 0) return 0;
    size_t n = len < r->sz ? len : r->sz;
    for (size_t i = 0; i < n; i++) { out[i]      = r->buf[r->rd];
        r->rd = inc(r->rd, r->cap);
    }
    r->sz -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *r, uint8_t *out, size_t len)
{
