    size_t lim = len < r->sz ? len : r->sz, c = 0;
    size_t p = r->rd;
    for (size_t i = 0; i < lim; i++) { out[i]     = r->buf[p];
        p = inc(p, r->cap); ++c;
    }
    return c;
